CREATE TABLE "accounts_userpreferences" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "theme" varchar(10) NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "providers_agentmodeloverride" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "persona" varchar(20) NOT NULL, "provider" varchar(20) NOT NULL, "model" varchar(200) NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_user_persona_override" UNIQUE ("user_id", "persona"));
CREATE TABLE "providers_aipreferences" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "default_provider" varchar(20) NOT NULL, "default_model" varchar(200) NOT NULL, "temperature" real NULL, "max_output_tokens" integer unsigned NULL CHECK ("max_output_tokens" >= 0), "updated_at" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "providers_providercredential" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(20) NOT NULL, "encrypted_key" text NOT NULL, "key_hint" varchar(8) NOT NULL, "last_test_status" varchar(10) NOT NULL, "last_test_message" varchar(500) NOT NULL, "last_tested_at" datetime NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_user_provider_key" UNIQUE ("user_id", "provider"));
CREATE TABLE "studio_generationjob" ("id" char(32) NOT NULL PRIMARY KEY, "kind" varchar(20) NOT NULL, "agent" varchar(40) NOT NULL, "status" varchar(12) NOT NULL, "input" text NOT NULL CHECK ((JSON_VALID("input") OR "input" IS NULL)), "result" text NULL CHECK ((JSON_VALID("result") OR "result" IS NULL)), "error" text NULL CHECK ((JSON_VALID("error") OR "error" IS NULL)), "usage" text NOT NULL CHECK ((JSON_VALID("usage") OR "usage" IS NULL)), "cancel_requested" bool NOT NULL, "boot_id" varchar(40) NOT NULL, "created_at" datetime NOT NULL, "started_at" datetime NULL, "finished_at" datetime NULL, "owner_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "retry_of_id" char(32) NULL REFERENCES "studio_generationjob" ("id") DEFERRABLE INITIALLY DEFERRED, "project_id" char(32) NULL REFERENCES "studio_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "studio_jobevent" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "seq" integer unsigned NOT NULL CHECK ("seq" >= 0), "type" varchar(30) NOT NULL, "agent" varchar(40) NOT NULL, "persona" varchar(20) NOT NULL, "message" varchar(500) NOT NULL, "data" text NOT NULL CHECK ((JSON_VALID("data") OR "data" IS NULL)), "created_at" datetime NOT NULL, "job_id" char(32) NOT NULL REFERENCES "studio_generationjob" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_job_event_seq" UNIQUE ("job_id", "seq"));
CREATE TABLE "studio_mediaasset" ("id" char(32) NOT NULL PRIMARY KEY, "kind" varchar(10) NOT NULL, "file_name" varchar(255) NOT NULL UNIQUE, "display_name" varchar(255) NOT NULL, "duration_seconds" real NULL, "size_bytes" bigint NOT NULL, "created_at" datetime NOT NULL, "job_id" char(32) NULL REFERENCES "studio_generationjob" ("id") DEFERRABLE INITIALLY DEFERRED, "owner_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "project_id" char(32) NULL REFERENCES "studio_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "studio_message" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "role" varchar(10) NOT NULL, "content" text NOT NULL, "persona" varchar(20) NOT NULL, "attachments" text NOT NULL CHECK ((JSON_VALID("attachments") OR "attachments" IS NULL)), "created_at" datetime NOT NULL, "job_id" char(32) NULL REFERENCES "studio_generationjob" ("id") DEFERRABLE INITIALLY DEFERRED, "project_id" char(32) NOT NULL REFERENCES "studio_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "studio_project" ("id" char(32) NOT NULL PRIMARY KEY, "title" varchar(120) NOT NULL, "title_locked" bool NOT NULL, "legacy_id" varchar(64) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "owner_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
